export const BODY: string = "\n<p>ضغط الصور بالجملة يعني معالجة عشرات الصور دفعة واحدة بدل واحدة تلو الأخرى. ترفع المجلد كاملًا، وتحدد الهدف مرة واحدة، وتنزّل كل شيء كملف ZIP.</p>\n<p>هذه الطريقة توفر ساعات للمدونين وأصحاب المتاجر والمصورين. بدل ضغط 50 صورة يدويًا، تنتهي الدفعة كاملة في دقائق.</p>\n<p>يشرح هذا الدليل كيف يعمل <a href=\"/ar/daght-jumli-lis-suwar/\">ضاغط الصور بالجملة</a>، ومتى تستخدمه، وكيف تحصل على أفضل النتائج من كل دفعة.</p>\n<h2 id=\"what-is-bulk-compression\">ما هو ضغط الصور بالجملة؟</h2>\n<p>الضغط بالجملة هو معالجة مجموعة صور كاملة بإعدادات واحدة. ترفع كل الصور، وتختار الهدف، وتشغّل الدفعة، وتنزّل النتائج معًا.</p>\n<p>الفكرة بسيطة لكنها قوية: بدل تكرار العملية 50 مرة، تفعلها مرة واحدة. الوقت الذي توفره هائل، والنتائج متسقة.</p>\n<h2 id=\"how-it-works\">كيف يعمل ضاغط الجملة؟</h2>\n<p>يعمل ضاغط الجملة بمعالجة كل صورة على حدة بإعداداتك نفسها. كل صورة تمر عبر البحث عن الجودة نفسها، وتصل إلى الهدف نفسه.</p>\n<p>تظهر النتائج تدريجيًا مع شريط تقدم. يمكنك متابعة كل صورة وهي تنتهي، ومعرفة أي صورة واجهت مشكلة فورًا.</p>\n<h2 id=\"presets-explained\">شرح الإعدادات الثلاثة الجاهزة</h2>\n<p>الإعدادات الجاهزة الثلاثة هي: خفيف للجودة العالية، ومتوازن للاستخدام العام، وصغير لأصغر حجم ممكن. كل إعداد يوازن بين الجودة والحجم بطريقة مختلفة.</p>\n<p>اختر خفيفًا لصور المحفظة، ومتوازنًا لصور المدونة، وصغيرًا للصور المصغرة والأيقونات. الاختيار الصحيح يختصر التجربة والخطأ.</p>\n<h2 id=\"when-to-use-bulk\">متى تستخدم الضغط بالجملة؟</h2>\n<p>استخدم الضغط بالجملة عندما يكون لديك عشر صور أو أكثر تحتاج الإعدادات نفسها. صور مدونة كاملة أو كتالوج متجر أو ألبوم صور كلها حالات مثالية.</p>\n<p>لا تستخدمه لصورة واحدة أو صورتين. الإعداد الفردي يعطي تحكمًا أفضل عندما تكون كل صورة حالة خاصة.</p>\n<h2 id=\"batch-vs-target-tools\">الجملة مقابل أدوات الهدف بالكيلوبايت</h2>\n<p>أدوات الجملة تضغط كل صورة إلى هدف واحد، بينما أدوات الهدف بالكيلوبايت تضغط صورة واحدة إلى حجم دقيق. الفرق هو الكمية مقابل الدقة.</p>\n<p>إذا احتجت حجمًا دقيقًا مثل 50 كيلوبايت لصورة واحدة، فاستخدم <a href=\"/ar/daght-as-sura-ila-hajm-muayyan/\">ضاغط حجم الملف المستهدف</a>. وإذا احتجت معالجة كمية، فالجملة أفضل. ولتحسين الصور لسرعة الموقع، استخدم <a href=\"/ar/tahsin-suwar-al-web/\">محسّن صور الويب</a>.</p>\n<h2 id=\"quality-in-batches\">الجودة في الدفعات</h2>\n<p>الجودة في الدفعات متسقة لأن كل صورة تحصل على الإعدادات نفسها. لكن الصور المختلفة تستجيب بشكل مختلف: صورة بسيطة قد تبدو ممتازة، وصورة مزدحمة قد تحتاج مراجعة.</p>\n<p>لذلك راجع عينة من النتائج دائمًا. إذا بدت العينة جيدة، فغالبًا الدفعة كلها بنفس الجودة.</p>\n<h2 id=\"formats-in-batches\">الصيغ المختلطة في دفعة</h2>\n<p>الدفعات تقبل صيغًا مختلطة: JPG وPNG وWebP وHEIC معًا. يمكنك رفع مجلد كامل دون فرز الصيغ أولًا.</p>\n<p>لكن انتبه إلى صور GIF المتحركة. الضغط الجماعي قد يعاملها كصور ثابتة، لذلك استخدم <a href=\"/ar/daght-gif/\">ضاغط GIF</a> المخصص للصور المتحركة.</p>\n<h2 id=\"zip-workflow\">سير عمل تنزيل ZIP</h2>\n<p>بعد انتهاء الدفعة، تنزّل كل النتائج كملف ZIP واحد. الملف يحافظ على أسماء الصور الأصلية، فيسهل العثور على كل صورة.</p>\n<p>فك ضغط الملف في مجلد جديد وراجع النتائج قبل الرفع. التنظيم الجيد يمنع الخلط بين النسخ الأصلية والمضغوطة.</p>\n<h2 id=\"phone-batches\">الضغط بالجملة على الهاتف</h2>\n<p>الضغط بالجملة يعمل على الهاتف أيضًا. افتح الأداة في المتصفح واختر عدة صور من معرضك دفعة واحدة.</p>\n<p>لكن انتبه إلى الذاكرة: الدفعات الكبيرة على الهاتف قد تستهلك ذاكرة كثيرة. للدفعات الكبيرة جدًا، استخدم الحاسوب.</p>\n<h2 id=\"common-mistakes\">أخطاء شائعة في الضغط بالجملة</h2>\n<p>أكثر الأخطاء شيوعًا رفع صور مضغوطة أصلًا. كل جولة ضغط تضيف ضررًا، فابدأ دائمًا من الملفات الأصلية بأعلى جودة.</p>\n<p>خطأ آخر أن تنسى مراجعة النتائج. صورة واحدة سيئة في دفعة من 50 قد تمر دون ملاحظة إذا لم تراجع عينة.</p>\n<h2 id=\"privacy-in-bulk\">الخصوصية في الضغط بالجملة</h2>\n<p>الخصوصية في الضغط بالجملة مثل الضغط الفردي: كل المعالجة تتم على جهازك، ولا تُرفع أي صورة إلى خادم.</p>\n<p>هذا مهم خصوصًا مع صور العملاء أو الصور الشخصية. يمكنك ضغط دفعة كاملة دون قلق بشأن تسرب البيانات.</p>\n<h2 id=\"batch-summary\">كيف تقرأ ملخص الدفعة؟</h2>\n<p>بعد انتهاء الدفعة، يعرض الملخص عدد الصور الناجحة والفاشلة وإجمالي التوفير في الحجم. اقرأ الملخص قبل التنزيل.</p>\n<p>إذا فشلت صورة واحدة، فلا تعيد الدفعة كاملة. أعد ضغط تلك الصورة وحدها بإعدادات مختلفة.</p>\n<h2 id=\"recompress-single\">كيف تعيد ضغط صورة عنيدة واحدة؟</h2>\n<p>إذا فشلت صورة واحدة في الوصول إلى الهدف، فأعد ضغطها وحدها. جرّب صيغة مختلفة أو قصًا أذكى أو أبعادًا أصغر.</p>\n<p>الصورة العنيدة غالبًا صورة مزدحمة بالتفاصيل أو بصيغة غير مناسبة. تغيير الصيغة إلى JPG يحل المشكلة في معظم الحالات.</p>\n<h2 id=\"dimension-consistency\">كيف تحافظ على اتساق الأبعاد في دفعة؟</h2>\n<p>للحفاظ على اتساق الأبعاد في دفعة، استخدم الإعدادات نفسها لكل الصور. الأداة تحافظ على أبعاد كل صورة ما لم تسمح بالتقليص.</p>\n<p>إذا احتجت أبعادًا موحدة، فغيّر حجم الصور أولًا بأداة تغيير الحجم الجماعي، ثم اضغطها. الترتيب الصحيح يعطي نتائج متسقة.</p>\n<h2 id=\"backup-strategy\">استراتيجية نسخ احتياطي للدفعات</h2>\n<p>قبل أي دفعة كبيرة، انسخ الملفات الأصلية احتياطيًا. الدفعة تستبدل الملفات أحيانًا إذا نسيت تغيير مجلد الإخراج.</p>\n<p>القاعدة الذهبية: الأصل في مجلد، والنسخ المضغوطة في مجلد آخر. لا تخلط بينهما أبدًا.</p>\n<h2 id=\"seasonal-batches\">دفعات موسمية للمتاجر والمدونات</h2>\n<p>الدفعات الموسمية توفر وقتًا للمتاجر والمدونات. جهّز صور العروض والأعياد دفعة واحدة قبل الموسم، واحفظها جاهزة للنشر.</p>\n<p>سمِّ مجلدات الدفعات حسب الموسم، مثل عروض-رمضان-2026. التنظيم يسهّل العثور على الصور عندما يحين وقتها.</p>\n<h2 id=\"accessibility-batches\">إمكانية الوصول في العمل بالجملة</h2>\n<p>إمكانية الوصول في العمل بالجملة تعني الحفاظ على النص البديل وأسماء الملفات الواضحة. الضغط لا يزيل النص البديل، لكن إعادة التسمية قد تفقده.</p>\n<p>احتفظ بأسماء الملفات الوصفية بعد الضغط. الاسم الواضح يساعد محركات البحث وقارئات الشاشة على فهم الصورة.</p>\n<h2 id=\"final-check\">مراجعة أخيرة قبل الرفع</h2>\n<p>قبل الرفع، راجع عينة من الدفعة: افتح 5 صور عشوائية وتأكد من جودتها وأبعادها وأسمائها.</p>\n<p>إذا بدت العينة جيدة، فالدفعة جاهزة. وللخطوات العملية، اقرأ <a href=\"/ar/blog/kayfiyya-daght-suwar-mutaaddida-marrah-wahida/\">كيفية ضغط عدة صور دفعة واحدة</a> و<a href=\"/ar/blog/afdal-mumarasat-li-daght-as-suwar-al-jumli/\">أفضل ممارسات ضغط الصور بالجملة</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كم صورة يمكنني ضغطها في دفعة واحدة؟","answer":"يعتمد على حجم الصور وجهازك، لكن الأداة تتعامل مع عشرات الصور دفعة واحدة بسهولة. للدفعات الكبيرة جدًا، قسّمها إلى مجموعات من 20 إلى 30 صورة."},{"question":"هل يغيّر الضغط بالجملة حجم صوري؟","answer":"الضغط لا يغيّر الأبعاد افتراضيًا. يحاول الوصول إلى الهدف بخفض الجودة أولًا، ولا يقلّص الأبعاد إلا عندما لا تكفي الجودة وحدها."},{"question":"ما الفرق بين الإعدادات الثلاثة الجاهزة للجملة؟","answer":"الإعدادات الثلاثة هي أوضاع جودة: خفيف للصور التي تحتاج جودة عالية، ومتوازن للاستخدام العام، وصغير لأصغر حجم ممكن. اختر حسب أولويتك بين الجودة والحجم."},{"question":"هل يمكنني إضافة مزيد من الصور بعد انتهاء الدفعة؟","answer":"لا، بعد بدء الدفعة لا يمكن إضافة صور إليها. أضف كل الصور قبل البدء، أو شغّل دفعة ثانية للصور الإضافية بعد انتهاء الأولى."},{"question":"لماذا ظهر تحذير بأن صورة في دفعتي كبر حجمها؟","answer":"يحدث ذلك عندما تكون الصورة الأصلية مضغوطة أصلًا بكفاءة، أو عندما تكون صيغة الإخراج أكبر من الأصل. تحقق من إعداداتك، واستخدم JPG للصور الفوتوغرافية."},{"question":"هل يمكنني ضغط صور GIF المتحركة في دفعة؟","answer":"نعم، يمكنك ضغط صور GIF المتحركة بالجملة، لكن الضغط الجماعي يعاملها كصور ثابتة أحيانًا. للصور المتحركة، استخدم ضاغط GIF المخصص للحفاظ على الحركة."}];
